# typed: strict
# frozen_string_literal: true

# This file is generated by scripts/gen-homebrew-formula.sh on each olai-trestle
# release. Do not edit by hand — edits will be overwritten on the next release.
class Trestle < Formula
  desc "Unified CLI for proto-driven code generation and full-project scaffolding"
  homepage "https://github.com/open-lakehouse/trestle"
  license "Apache-2.0"
  # No explicit `version`: Homebrew scans it from the `olai-trestle-v<version>`
  # segment of the download URLs (an explicit line trips FormulaAudit/Version as
  # redundant).

  # No `livecheck` block on purpose: this is our own tap, and the
  # `bump-homebrew` CI job regenerates this formula on every olai-trestle release,
  # so there is nothing for Homebrew's autobump bot to discover. (A livecheck
  # here would also need a per-crate tag filter — other workspace crates tag
  # under different prefixes — which `url :stable` cannot express.)

  on_macos do
    on_arm do
      url "https://github.com/open-lakehouse/trestle/releases/download/olai-trestle-v0.0.23/trestle-aarch64-apple-darwin.tar.gz"
      sha256 "aafc83d9612f781ce7951b441f0761b50e2cfa8b030861382d2a0e44332dd407"
    end
    on_intel do
      url "https://github.com/open-lakehouse/trestle/releases/download/olai-trestle-v0.0.23/trestle-x86_64-apple-darwin.tar.gz"
      sha256 "b6a0b77a27ee2e65ef020febd8e73b115048649360b37b8a65b5a3d4e37f1879"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/open-lakehouse/trestle/releases/download/olai-trestle-v0.0.23/trestle-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "f82a210e3b2338cedd4d427b096f8a2091b11a601f7c2fb3c1926fa213fa4c2e"
    end
    on_intel do
      url "https://github.com/open-lakehouse/trestle/releases/download/olai-trestle-v0.0.23/trestle-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "0916872d56bd881997beb474b036e0b7a3bf933e5f7ed97ba416dfd6aa6fea82"
    end
  end

  # release-binaries.yml packages with `leading-dir: true`, so every archive
  # unpacks to a single `trestle-<target>/` directory containing the binary.
  # Homebrew does not strip that dir, so glob for the binary wherever it landed
  # rather than hard-coding the per-platform target triple.
  def install
    bin.install Dir["**/trestle"].first
  end

  test do
    assert_match "trestle", shell_output("#{bin}/trestle --version")
  end
end
